const canonicalRows = (payload: unknown): Array<Record<string, unknown>> => {
  if (Array.isArray(payload)) return payload as Array<Record<string, unknown>>;
  if (!payload || typeof payload !== 'object') return [];
  const object = payload as Record<string, unknown>;
  for (const key of ['rows', 'data', 'items', 'products', 'documents']) {
    if (Array.isArray(object[key])) return object[key] as Array<Record<string, unknown>>;
  }
  return object.id ? [object] : [];
};

const readLocalCanonicalTable = async (table: string) => {
  const endpoint = canonicalReadEndpoints[table];
  if (!endpoint) return null;
  const paged = ['orders', 'quotes', 'ghn_tracking', 'fabric_transactions', 'production_orders'].includes(table);
  const rows: Array<Record<string, unknown>> = [];
  for (let offset = 0; ; offset += 500) {
    const url = new URL(`${localApiUrl()}${endpoint}`);
    if (paged) {
      url.searchParams.set('limit', '500');
      url.searchParams.set('offset', String(offset));
      url.searchParams.set('page', String(offset / 500 + 1));
      url.searchParams.set('pageSize', '500');
    }
    const response = await localFetch(url);
    const payload = await response.json();
    if (!response.ok) throw new Error(payload.message || `Local API lỗi (${response.status}).`);
    const batch = canonicalRows(payload);
    rows.push(...batch);
    if (!paged || batch.length < 500 || (Number.isFinite(payload?.total) && rows.length >= payload.total)) break;
  }
  return rows;
};

const matchesLocalFilter = (row: Record<string, unknown>, filter: LocalFilter): boolean => {
  if (filter.kind === 'or') {
    return (filter.value as Array<{ column: string; value: unknown; operator?: string }>).some((item) => {
      const actual = row[item.column];
      if (item.operator === 'eq') return actual === item.value;
      return String(actual ?? '').toLowerCase().includes(String(item.value).toLowerCase());
    });
  }
  const actual = row[filter.column];
  if (filter.kind === 'eq') return actual === filter.value;
  if (filter.kind === 'ilike') return String(actual ?? '').toLowerCase().includes(String(filter.value).replace(/%/g, '').toLowerCase());
  if (filter.kind === 'in') return Array.isArray(filter.value) && filter.value.includes(actual);
  if (filter.kind === 'is') return filter.value === null ? actual == null : actual === filter.value;
  if (filter.kind === 'not' || filter.kind === 'neq') {
    if (filter.operator === 'is' && filter.value === null) return actual != null;
    return actual !== filter.value;
  }
  if (filter.kind === 'contains') {
    if (Array.isArray(actual)) return Array.isArray(filter.value) && filter.value.every((item) => actual.includes(item));
    return String(actual ?? '').toLowerCase().includes(String(filter.value ?? '').toLowerCase());
  }
  if (filter.kind === 'gt' || filter.kind === 'gte' || filter.kind === 'lt' || filter.kind === 'lte') {
    const actualNumber = typeof actual === 'number' ? actual : Number(actual);
    const valueNumber = typeof filter.value === 'number' ? filter.value : Number(filter.value);
    const numeric = Number.isFinite(actualNumber) && Number.isFinite(valueNumber) && String(actual ?? '').trim() !== '';
    const left = numeric ? actualNumber : String(actual ?? '');
    const right = numeric ? valueNumber : String(filter.value ?? '');
    if (filter.kind === 'gt') return left > right;
    if (filter.kind === 'gte') return left >= right;
    if (filter.kind === 'lt') return left < right;
    return left <= right;
  }
  return true;
};

const readLocalSnapshotTable = async (table: string, filters: LocalFilter[], order?: { column: string; ascending: boolean }, offset = 0, limit?: number) => {
  const canonical = await readLocalCanonicalTable(table);
  if (canonical) {
    let rows = canonical.filter((row) => filters.every((filter) => matchesLocalFilter(row, filter)));
    if (order) rows = [...rows].sort((left, right) => {
      const result = String(left[order.column] ?? '').localeCompare(String(right[order.column] ?? ''), undefined, { numeric: true });
      return order.ascending ? result : -result;
    });
    return { rows: sliceLocalRows(rows, { offset, limit }), total: rows.length };
  }
  const allRows: Array<Record<string, unknown>> = [];
  let cursor = 0;
  let total = 0;
  do {
    const response = await localFetch(`${localApiUrl()}/api/local-snapshot/${encodeURIComponent(table)}?limit=100&offset=${cursor}`);
    const payload = await response.json() as { rows?: Array<{ source_key: string; payload: Record<string, unknown> }>; total?: number };
    if (!response.ok) throw new Error((payload as { message?: string }).message || `Local API lỗi (${response.status}).`);
    total = Number(payload.total || 0);
    for (const row of payload.rows || []) allRows.push({ id: row.source_key, ...row.payload });
    cursor += 100;
  } while (cursor < total);

  let rows = allRows.filter((row) => filters.every((filter) => matchesLocalFilter(row, filter)));
  if (order) {
    rows = [...rows].sort((left, right) => {
      const a = left[order.column];
      const b = right[order.column];
      const result = String(a ?? '').localeCompare(String(b ?? ''), undefined, { numeric: true });
      return order.ascending ? result : -result;
    });
  }
  return { rows: sliceLocalRows(rows, { offset, limit }), total: rows.length };
};

const createLocalQuery = (table: string) => {
  const state: { filters: LocalFilter[]; order?: { column: string; ascending: boolean }; offset: number; limit?: number; mode: 'select' | 'insert' | 'update' | 'delete' | 'upsert'; body?: unknown; one: boolean; maybeOne: boolean; count?: 'exact' | 'planned' | 'estimated'; head: boolean } = {
    filters: [], offset: 0, mode: 'select', one: false, maybeOne: false, head: false,
  };
  const execute = async () => {
    if (state.mode !== 'select') {
      try {
        const endpointMap: Record<string, string> = {
          customers: '/api/customers',
          quotes: '/api/quotes',
          orders: '/api/orders',
          contracts: '/api/contracts',
          transactions: '/api/transactions',
          order_payments: '/api/order-payments',
          assignees: '/api/assignees',
          expenses: '/api/expenses',
          shipping_companies: '/api/shipping-companies',
          ghn_tracking: '/api/ghn-tracking',
          products: '/api/catalog/products',
          inventory_items: '/api/inventory/items',
          fabric_types: '/api/fabrics/types',
          fabric_variants: '/api/fabrics/variants',
          fabric_widths: '/api/fabrics/widths',
          fabric_inventory: '/api/fabrics/inventory',
          fabric_transactions: '/api/fabrics/transactions',
          fabric_transfers: '/api/fabrics/transfers',
          knowledge_documents: '/api/knowledge/documents',
        };
        const base = `${localApiUrl()}${endpointMap[table] || canonicalWriteEndpoints[table] || `/api/local-table/${encodeURIComponent(table)}`}`;
        if (state.mode === 'insert' || state.mode === 'upsert') {
          const bodies = Array.isArray(state.body) ? state.body : [state.body];
          const collected: unknown[] = [];
          for (const body of bodies) {
            const response = await localFetch(base, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
            const data = await response.json();
            if (!response.ok) return { data: null, error: data };
            collected.push(...(Array.isArray(data) ? data : (data?.rows || data?.data || [data])));
          }
          const rows = collected;
          return { data: state.one || state.maybeOne ? (rows[0] || null) : rows, error: null };
        }
        const filterSpec = validateLocalMutationFilters(table, state.mode as 'update' | 'delete', state.filters.map((filter) => ({ kind: filter.kind, column: filter.column, value: filter.value })));
        if (filterSpec.kind === 'products-price-list') {
          const response = await localFetch(`${base}/by-price-list/${encodeURIComponent(String(filterSpec.value))}`, { method: 'DELETE' });
          const data = await response.json();
          if (!response.ok) return { data: null, error: data };
          return { data: state.one || state.maybeOne ? (data || null) : [data], error: null };
        }
        const targets = filterSpec.kind === 'ids' && Array.isArray(filterSpec.value) ? filterSpec.value : [filterSpec.value];
        const results: unknown[] = [];
        for (const target of targets) {
          const endpoint = state.mode === 'delete' && ['ghn_tracking', 'transactions'].includes(table) && filterSpec.kind === 'natural' && filterSpec.column === 'order_id'
            ? `${base}/by-order/${encodeURIComponent(String(target))}`
            : state.mode === 'delete' && table === 'order_payments' && filterSpec.kind === 'id'
            ? `${base}/by-id/${encodeURIComponent(String(target))}`
            : state.mode === 'delete' && table === 'order_payments' && filterSpec.kind === 'natural' && filterSpec.column === 'order_id'
            ? `${base}/${encodeURIComponent(String(target))}`
            : filterSpec.kind === 'natural'
            ? `${base}/by-key/${encodeURIComponent(String(target))}`
            : `${base}/${encodeURIComponent(String(target))}`;
          const response = await localFetch(endpoint, {
            method: state.mode === 'delete' ? 'DELETE' : 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: state.mode === 'delete' ? undefined : JSON.stringify(state.body || {}),
          });
          const data = await response.json();
          if (!response.ok) return { data: null, error: data };
          results.push(data);
        }
        return { data: state.one || state.maybeOne ? (results[0] || null) : results, error: null };
      } catch (error) { return { data: null, error: { message: error instanceof Error ? error.message : 'Không thể ghi local.' } }; }
    }
    try {
      const result = await readLocalSnapshotTable(table, state.filters, state.order, state.offset, state.limit);
      return localSelectResult(result.rows, result.total, { one: state.one, maybeOne: state.maybeOne, head: state.head, count: Boolean(state.count) });
    } catch (error) {
      return { data: state.one || state.maybeOne ? null : [], error: { message: error instanceof Error ? error.message : 'Không thể đọc snapshot local.' } };
    }
  };
  const target: Record<string, unknown> = {};
  const proxy = new Proxy(target, {
    get(_target, property: string | symbol) {
      if (property === 'then') return (resolve: (value: unknown) => unknown, reject: (reason: unknown) => unknown) => execute().then(resolve, reject);
      if (property === 'catch') return (reject: (reason: unknown) => unknown) => execute().catch(reject);
      if (property === 'finally') return (callback: () => void) => execute().finally(callback);
      if (property === 'select') return (_columns?: string, options?: { count?: 'exact' | 'planned' | 'estimated'; head?: boolean }) => { state.count = options?.count; state.head = Boolean(options?.head); return proxy; };
      if (property === 'eq' || property === 'ilike' || property === 'is' || property === 'gt' || property === 'gte' || property === 'lt' || property === 'lte') return (column: string, value: unknown) => { state.filters.push({ kind: property, column, value } as LocalFilter); return proxy; };
      if (property === 'not') return (column: string, operator: string, value: unknown) => { state.filters.push({ kind: 'not', column, value, operator }); return proxy; };
      if (property === 'neq') return (column: string, value: unknown) => { state.filters.push({ kind: 'neq', column, value }); return proxy; };
      if (property === 'in') return (column: string, value: unknown[]) => { state.filters.push({ kind: 'in', column, value }); return proxy; };
      if (property === 'contains') return (column: string, value: unknown) => { state.filters.push({ kind: 'contains', column, value }); return proxy; };
      if (property === 'or') return (expression: string) => {
        const parts = expression.split(',').map((part) => part.trim()).filter(Boolean);
        const items = parts.map((part) => {
          const match = part.match(/^([\w]+)\.(ilike|eq)\.(.*)$/i);
          if (!match) throw new Error(`Local API chưa hỗ trợ biểu thức OR: ${part}`);
          const operator = match[2].toLowerCase();
          const rawValue = match[3];
          return { column: match[1], operator, value: operator === 'ilike' ? rawValue.replace(/^%|%$/g, '') : rawValue };
        });
        if (items.length) state.filters.push({ kind: 'or', column: '', value: items });
        return proxy;
      };
      if (property === 'order') return (column: string, options?: { ascending?: boolean }) => { state.order = { column, ascending: options?.ascending !== false }; return proxy; };
      if (property === 'range') return (from: number, to: number) => { state.offset = from; state.limit = Math.max(0, to - from + 1); return proxy; };
      if (property === 'limit') return (value: number) => { state.limit = value; return proxy; };
      if (property === 'single') return () => { state.one = true; return proxy; };
      if (property === 'maybeSingle') return () => { state.maybeOne = true; return proxy; };
      if (property === 'insert' || property === 'update' || property === 'delete' || property === 'upsert') return (body?: unknown, _options?: unknown) => { state.mode = property; state.body = body; return proxy; };
      return undefined;
    },
  });
  return proxy;
};

const localUnavailable = new Proxy({}, {
  get(_target, property) {
    if (property === 'auth') return localAuth;
    if (property === 'channel') return localChannel;
    if (property === 'removeChannel') return (channel: { unsubscribe?: () => string }) => {
      channel?.unsubscribe?.();
      localChannels.delete(channel as { unsubscribe: () => string });
      return Promise.resolve('ok');
    };
    if (property === 'storage') return { from: (bucket: string) => localStorageBucket(bucket) };
    if (property === 'rpc') return async (name: string, args?: Record<string, unknown>) => {
      try {
        const response = await localFetch(`${localApiUrl()}/api/local-rpc/${encodeURIComponent(name)}`, {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify(args || {}),
        });
        const payload = await response.json().catch(() => ({}));
        if (!response.ok) return { data: null, error: payload };
        return { data: payload.data ?? payload, error: null };
      } catch (error) {
        return { data: null, error: { message: error instanceof Error ? error.message : 'Local RPC lỗi.' } };
      }
    };
    if (property === 'functions') return { invoke: async (name: string, options?: { method?: string; body?: unknown }) => {
      try {
        const method = options?.method || 'POST';
      const response = await localFetch(`${localApiUrl()}/api/local-functions/${encodeURIComponent(name)}`, { method, headers: { 'content-type': 'application/json' }, body: method === 'GET' ? undefined : JSON.stringify(options?.body || {}) });
        const payload = await response.json().catch(() => ({}));
        return response.ok ? { data: payload, error: null } : { data: null, error: payload };
      } catch (error) { return { data: null, error: { message: error instanceof Error ? error.message : 'Local Function lỗi.' } }; }
    } };
    if (property === 'from') return (table: string) => createLocalQuery(table);
    throw new Error('Mô-đun này chưa có Local API. Dữ liệu Supabase public vẫn được giữ nguyên.');
  },
}) as unknown as SupabaseClient<ProductionManagementDatabase>;

export const supabase = LOCAL_BACKEND
  ? localUnavailable
  : createClient<ProductionManagementDatabase>(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, {
      auth: {
        storage: localStorage,
        persistSession: true,
        autoRefreshToken: true,
      },
    });
